INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Phablet immer größer als ein Smartphone?', 2, '[{"text": "Ja", "correct": true, "because": "Bildschirmgröße über 5,5 Zoll definiert Phablets"}, {"text": "Nein", "correct": false, "because": "Kleiner als Tablets, aber größer als Smartphones"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptmerkmal eines Phablets?', 3, '[{"text": "Großer Bildschirm", "correct": true, "because": "Zwischen 5,5 und 7 Zoll für Multimedia"}, {"text": "Kleine Größe", "correct": false, "because": "Nicht typisch für Phablets"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Touchscreen ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen unterstützt ein Phablet typischerweise?', 5, '[{"text": "Telefonie", "correct": true, "because": "Wie ein Smartphone"}, {"text": "Multimedia", "correct": true, "because": "Großer Bildschirm ideal"}, {"text": "3D-Modellierung", "correct": false, "because": "Spezialisierte Software nötig"}, {"text": "Serververwaltung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Phablets nutzen oft Stylus-Eingaben. b) Sie ersetzen immer Laptops.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht universell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Phablets?', 4, '[{"text": "Bildschirmgröße", "correct": false, "because": "Definiert Nutzung"}, {"text": "Batterielaufzeit", "correct": false, "because": "Wichtig für Mobilität"}, {"text": "Farbe der Verpackung", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Phablet immer Android nutzt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch iOS möglich"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv Android"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist für die Leistung eines Phablets entscheidend?', 3, '[{"text": "Prozessorleistung", "correct": true, "because": "Beeinflusst Geschwindigkeit"}, {"text": "Gewicht", "correct": false, "because": "Sekundär für Leistung"}, {"text": "Manuelle Updates", "correct": false, "because": "Automatisch besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Phablet?', 5, '[{"text": "Multimedia-Komfort", "correct": true, "because": "Großer Bildschirm"}, {"text": "Portabilität", "correct": true, "because": "Kleiner als Tablets"}, {"text": "Serverfunktion", "correct": false, "because": "Nicht typisch"}, {"text": "Einfache Reparatur", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Phablets sind ideal für Gaming. b) Sie sind immer faltbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht universell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Einsatz eines Phablets?', 4, '[{"text": "Betriebssystem", "correct": false, "because": "Notwendig für Funktion"}, {"text": "Internetzugang", "correct": false, "because": "Für viele Funktionen nötig"}, {"text": "Externe Festplatte", "correct": true, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Haben Phablets immer Telefonfunktion?', 2, '[{"text": "Ja", "correct": true, "because": "Unterschied zu Tablets"}, {"text": "Nein", "correct": false, "because": "Telefonie ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte gelten als Phablets?', 4, '[{"text": "Galaxy Note", "correct": true, "because": "Pionier mit 5,3 Zoll"}, {"text": "iPhone 6 Plus", "correct": true, "because": "5,5 Zoll Bildschirm"}, {"text": "iPad Mini", "correct": false, "because": "Tablet, nicht Phablet"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Phablets immer teurer sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Preise variieren"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig teurer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl eines Phablets?', 3, '[{"text": "Bildschirmqualität", "correct": true, "because": "Entscheidend für Nutzung"}, {"text": "Geringe Größe", "correct": false, "because": "Nicht Phablet-typisch"}, {"text": "Manuelle Updates", "correct": false, "because": "Automatisch besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Phablets haben größere Akkus. b) Sie ersetzen Tablets.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht universell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei Phablets?', 5, '[{"text": "Portabilität", "correct": true, "because": "Größer als Smartphones"}, {"text": "Einhandbedienung", "correct": true, "because": "Schwierig bei großen Bildschirmen"}, {"text": "Geringe Akkulaufzeit", "correct": false, "because": "Oft besser als Smartphones"}, {"text": "Einfache Reparatur", "correct": false, "because": "Nicht typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Phablet unwichtig?', 3, '[{"text": "Prozessorleistung", "correct": false, "because": "Bestimmt Geschwindigkeit"}, {"text": "Bildschirmgröße", "correct": false, "because": "Definiert Phablet"}, {"text": "Verpackungsdesign", "correct": true, "because": "Kein Funktionsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützen Phablets 5G?', 3, '[{"text": "Ja", "correct": true, "because": "Moderne Modelle oft 5G-fähig"}, {"text": "Nein", "correct": false, "because": "Viele unterstützen 5G"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Phablets für ältere Nutzer vorteilhaft sind?', 2, '[{"text": "Ja", "correct": true, "because": "Größere Bildschirme helfen bei Sicht"}, {"text": "Nein", "correct": false, "because": "Vorteilhaft für Sichtbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Phablet?', 4, '[{"text": "Multimedia-Konsum unterwegs", "correct": true, "because": "Großer Bildschirm ideal"}, {"text": "Serverwartung", "correct": false, "because": "Andere Geräte"}, {"text": "3D-Druck", "correct": false, "because": "Spezialisierte Hardware"}]');
